import{_ as t,o as a,c as s,b6 as e,gE as l,gF as o,gG as r,gH as h,gI as p,gJ as n,gK as u,gL as g,gM as d,gN as b,gO as c,gP as k,gQ as m,gR as G,gS as H,gT as S,gU as q,gV as f,gW as y,gX as F,gY as _}from"./chunks/framework.BUXTSoD9.js";const A=JSON.parse('{"title":"Git 和 GitHub 工作流","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/backend/git-workflow/index.md","filePath":"zh-tw/stage-2/backend/git-workflow/index.md"}'),C={name:"zh-tw/stage-2/backend/git-workflow/index.md"};function x(E,i,P,B,T,v){return a(),s("div",null,[...i[0]||(i[0]=[e('<h1 id="git-和-github-工作流" tabindex="-1">Git 和 GitHub 工作流 <a class="header-anchor" href="#git-和-github-工作流" aria-label="Permalink to “Git 和 GitHub 工作流”">​</a></h1><p>在之前的課程中，我們學習瞭如何使用基於 Web 的 vibe coding 工具編寫程式碼。每次對話都會創建一個新版本的程式碼。但是，讓我們思考一個問題：如果我們想恢復到之前的修改，有沒有方便的方法？有沒有一種工具可以記錄我們在不同階段的程式碼，使我們能夠隨時在不同版本之間切換和修改？</p><p>為了滿足這一需求，版本控制軟體應運而生。在這篇文章中，我們將介紹最著名的版本控制程序——Git——以及最好的程式碼託管平臺——GitHub。我們將學習如何使用 Git 進行程式碼管理，如何從 GitHub 獲取他人的程式碼，如何上傳我們自己的程式碼，以及如何與他人合作進行大型項目。</p><p>無論是個人項目的版本跟蹤，團隊協作中的程式碼同步，還是為開源社區做貢獻，Git 和 GitHub 都是現代開發者的必備工具。通過掌握它們，你將能夠更高效地管理程式碼，根據需要創建檢查點，在程式碼的不同階段之間自由切換，並輕鬆處理從單個文件更改到開發大型項目的所有事務——使每一次程式碼迭代都可控且可追溯。</p><blockquote><p>💡 <strong>前置知識</strong></p><p>在學習 Git 之前，建議你先了解以下概念：</p><ul><li><a href="/easy-vibe-ja-learning-map/zh-tw/appendix/2-development-tools/command-line-shell.html">什麼是終端/命令行</a> - 學習如何使用命令行與計算機交互</li><li><a href="/easy-vibe-ja-learning-map/zh-tw/appendix/2-development-tools/git-version-control.html">什麼是 Git</a> - 瞭解 Git 版本控制系統的核心概念</li></ul><p>本文將重點介紹 GitHub 工作流和實際操作，上述基礎知識請參考附錄鏈接。</p></blockquote><h1 id="git-快速開始" tabindex="-1">Git 快速開始 <a class="header-anchor" href="#git-快速開始" aria-label="Permalink to “Git 快速開始”">​</a></h1><p>在開始使用 Git 之前，請確保你已經閱讀了附錄中關於<a href="/easy-vibe-ja-learning-map/zh-tw/appendix/2-development-tools/command-line-shell.html">命令行</a>和<a href="/easy-vibe-ja-learning-map/zh-tw/appendix/2-development-tools/git-version-control.html">Git 基礎</a>的內容。本文將假設你已經具備這些基礎知識，並直接講解如何安裝配置 Git 以及使用 GitHub 進行協作。</p><h2 id="如何安裝-git" tabindex="-1">如何安裝 Git <a class="header-anchor" href="#如何安裝-git" aria-label="Permalink to “如何安裝 Git”">​</a></h2><p>我們將演示在不同計算機操作系統上安裝 Git 的三種方法。請根據你的系統版本按照說明進行操作：</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><ol><li><p>前往 <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git 官方下載頁面</a> 並下載適合你係統的安裝程序：<a href="https://github.com/git-for-windows/git/releases/download/v2.51.0.windows.1/Git-2.51.0-64-bit.exe" target="_blank" rel="noreferrer">安裝包</a>。默認情況下，推薦使用 x64 安裝程序。</p></li><li><p>雙擊安裝程序並按照安裝嚮導說明進行操作： <img src="'+l+'" alt=""></p><ol><li>建議保持默認選項。如果你需要自定義，請注意以下幾點：（在大多數情況下，你可以一直點擊&quot;Next&quot;） <ul><li>選擇 Git 使用的默認編輯器：選擇你喜歡的編輯器（如 VS Code）。你可以默認選擇第一個選項，即 Vim（一個文本編輯器），或選擇&quot;Visual Studio Code as Git&#39;s default editor&quot;選項（需要預先安裝 VS Code）。你可以保持默認選擇並點擊&quot;Next&quot;繼續。 <img src="'+o+'" alt=""></li><li>選擇如何使用 Git：這三個選項控制 Git 在系統中的可訪問性。建議選擇選項 2（&quot;from command line and 3rd-party software&quot;）——它將基本的 Git 工具添加到 PATH 中，讓你可以在 Git Bash、命令提示符、PowerShell 和 IDE 中使用 Git，而不會使系統混亂。 <img src="'+r+'" alt=""></li></ul></li></ol></li><li><p>安裝後，在桌面上右鍵單擊。如果在菜單中看到&quot;Git Bash Here&quot;，則安裝成功。</p></li></ol><p><img src="'+h+`" alt=""></p><h3 id="macos" tabindex="-1">MacOS <a class="header-anchor" href="#macos" aria-label="Permalink to “MacOS”">​</a></h3><p>對於 macOS，你可以首先在終端中輸入 <code>git --version</code> 來檢查是否已經安裝了 Git。如果沒有，系統會提示你安裝——只需按照說明完成安裝即可。</p><ol><li>方法 1：通過 Homebrew 安裝 如果你安裝了 <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a>（Mac 包管理器），請打開終端並輸入<div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div></li><li>方法 2：（推薦）通過 Xcode 安裝： <a href="https://developer.apple.com/xcode/" target="_blank" rel="noreferrer">https://developer.apple.com/xcode/</a> ，Xcode 內置了 Git。安裝後，只需按照說明繼續操作。</li></ol><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>大多數 Linux 發行版可以通過其包管理器安裝 Git：</p><ul><li>Ubuntu/Debian:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>CentOS/RHEL:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>驗證安裝：在終端中輸入 git --version。如果顯示版本號，則安裝成功。</li></ul><h2 id="git-初始化" tabindex="-1">Git 初始化 <a class="header-anchor" href="#git-初始化" aria-label="Permalink to “Git 初始化”">​</a></h2><p>安裝 Git 後，你首先需要配置你的用戶資訊——這是使用 Git 進行版本控制的基本步驟。在終端中執行以下命令（將括號中的內容替換為你自己的資訊）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 設置全局用戶名（將顯示在提交記錄中）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 設置全局郵箱（建議使用在 GitHub/GitLab 等平臺上註冊的郵箱）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>Git 會將此資訊嵌入到每個提交記錄中，作為每次修改的&quot;作者資訊&quot;。查看版本歷史記錄（例如，使用 git log）時，你可以清楚地看到誰修改了每一行程式碼，便於追溯責任和溝通。在協作項目中，統一的身份資訊使團隊成員能夠快速識別誰做了哪些更改，從而提高協作效率（例如通過提交記錄找到相關開發人員討論問題）。</p><p>你可以通過在命令行中輸入 <code>git config --list</code> 來查看當前的 Git 配置資訊，以確認設置成功。</p><h1 id="什麼是-github" tabindex="-1">什麼是 GitHub <a class="header-anchor" href="#什麼是-github" aria-label="Permalink to “什麼是 GitHub”">​</a></h1><p>GitHub 是一個基於 Git 的程式碼託管平臺。它不僅為 Git 倉庫提供遠程存儲，還包括協作工具（如 Issues、Pull Requests、Projects），使開發者更容易分享程式碼和協作。簡而言之，Git 是一個本地版本控制工具，而 GitHub 是一個遠程&quot;程式碼倉庫雲盤 + 協作社區&quot;。</p><p>GitHub 不僅是世界上最大的程式碼託管平臺，也是全球最活躍、最具影響力的開源社區。這裡&quot;開源&quot;的核心思想是任何人都可以下載並運行軟體的源程式碼。這種模式允許世界各地的人們檢查彼此的程式碼並進行修改，或基於此創建新項目。例如，你可以在 GitHub 上找到各種學習教程以及用於訓練 GPT 模型的框架（如 PyTorch）的完整源程式碼。每天，無數人在全球範圍內協作審查和改進程式碼。</p><p><img src="`+p+'" alt=""></p><p>許多大公司在 GitHub 上開源他們的程序或教程，以獲得行業競爭優勢——這也可以看作是一種廣告形式。在 GitHub 社區中，項目獲得的&quot;星標 (stars)&quot;數量是衡量其價值的主要指標；項目或組織擁有的星標越多，其可信度和影響力就越大。</p><p><img src="'+n+'" alt=""></p><p>在我們的課程中，支持資源和作業也將上傳到專用的 GitHub 倉庫。通過上傳作業的過程，你將逐漸熟悉並掌握 GitHub 的使用，為未來應用程序開發中的版本控制打下堅實的基礎。</p><h2 id="註冊-github-賬號" tabindex="-1">註冊 GitHub 賬號 <a class="header-anchor" href="#註冊-github-賬號" aria-label="Permalink to “註冊 GitHub 賬號”">​</a></h2><ol><li>訪問 <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub 官網</a> 並點擊右上角的&quot;Sign up&quot;。 <img src="'+u+'" alt=""></li><li>輸入你的電子郵件地址（建議使用常用郵箱，因為驗證和通知將發送到那裡），設置密碼（必須包含字母、數字和特殊字符）。</li><li>完成人工驗證，按照提示驗證郵箱，你的賬號就創建好了。</li></ol><h2 id="在-github-上創建你的第一個倉庫" tabindex="-1">在 GitHub 上創建你的第一個倉庫 <a class="header-anchor" href="#在-github-上創建你的第一個倉庫" aria-label="Permalink to “在 GitHub 上創建你的第一個倉庫”">​</a></h2><p>接下來，我們將創建第一個存儲文件夾，也稱為倉庫或&quot;repo&quot;。</p><p><img src="'+g+'" alt=""><img src="'+d+'" alt=""></p><p><img src="'+b+'" alt=""></p><ol><li>Repository name：向他人顯示的倉庫名稱。</li><li>Description：倉庫的詳細描述。</li><li>Choose visibility：對於個人倉庫，如果設置為 private，只有你和特別邀請的人可以看到。如果設置為 public，所有人都可以看到。 對於組織內的倉庫，如果是 Private，只有組織內的人可以看到。 如果是 Public，組織外的人也可以看到。</li><li>README：通常的慣例是每個倉庫都應該有一個 README 文件。你可以把它看作是倉庫的完整介紹，包括使用說明、文件列表和操作方法。</li><li>Add .gitignore and license： <ol><li>.gitignore 文件告訴 Git 在上傳到 GitHub 時忽略某些文件夾或文件，因此它們不會被跟蹤或添加到暫存區。這對於臨時測試文件、依賴包或大文件很有用。一旦指定，這些文件將不再被跟蹤。</li><li>license 指的是你選擇的開源許可證類型。不同的許可證詳細規定了他人是否可以將你的程式碼用於商業目的，幷包含其他條款和條件。</li></ol></li></ol><p>建議勾選&quot;Add README&quot;，將倉庫可見性設置為&quot;Private&quot;，並根據自己的喜好填寫倉庫名稱和描述，然後點擊&quot;Create repository&quot;完成創建第一個遠程倉庫。</p><p><img src="'+c+'" alt=""></p><p>之後，你將擁有一個沒有任何額外文件的乾淨倉庫。接下來你可以開始上傳文件了。</p><p><img src="'+k+'" alt=""></p><p>獲取倉庫的命令是 <code>git clone</code>，但它需要倉庫地址。你可以通過點擊綠色的&quot;Code&quot;按鈕找到倉庫地址，你會看到 HTTPS 和 SSH 選項。通常，你可以使用這兩種方法中的任何一種將倉庫下載到本地機器（只有這樣你才能修改和上傳文件）。</p><p><img src="'+m+'" alt=""></p><p>一般來說，通過 HTTP 克隆的倉庫適合臨時下載和測試他人的倉庫，但不建議用於自己的開發。為了更好的學習體驗，你應該先設置 SSH 認證。</p><h2 id="綁定本地-ssh" tabindex="-1">綁定本地 SSH <a class="header-anchor" href="#綁定本地-ssh" aria-label="Permalink to “綁定本地 SSH”">​</a></h2><p>在 GitHub 中，&quot;SSH 協議綁定&quot;本質上意味著將你本地設備的 SSH 公鑰與你的 GitHub 賬號關聯，允許 GitHub 通過 SSH 協議識別你的設備。這使你能夠安全地操作遠程倉庫，而無需密碼（如 clone、push 或 pull 程式碼）。</p><p>簡單來說：這就像給你的設備一張&quot;GitHub 專屬門禁卡&quot;。綁定後，當你的設備通過 SSH 協議訪問 GitHub 倉庫時，GitHub 會驗證這張&quot;門禁卡&quot;（你的 SSH 公鑰）。一旦確認為你的授權設備，你就可以直接操作——不需要每次都輸入賬號密碼。</p><blockquote><p>💡 什麼是 SSH</p></blockquote><h3 id="為什麼需要-ssh-協議綁定" tabindex="-1">為什麼需要 SSH 協議綁定？ <a class="header-anchor" href="#為什麼需要-ssh-協議綁定" aria-label="Permalink to “為什麼需要 SSH 協議綁定？”">​</a></h3><p>GitHub 支持兩種主要的倉庫操作協議：HTTPS 協議和 SSH 協議：</p><ul><li>HTTPS 協議：每次操作（如 push）都需要輸入 GitHub 賬號密碼（或個人訪問令牌 PAT）。驗證過程繁瑣，且存在密碼洩露風險。</li><li>SSH 協議：身份驗證通過&quot;密鑰對&quot;完成，因此不需要重複輸入密碼，且加密傳輸更加安全。</li></ul><p>&quot;SSH 協議綁定&quot;是啟用 GitHub SSH 認證的前提步驟——只有將本地 SSH 公鑰&quot;綁定&quot;到 GitHub 賬號後，GitHub 才能識別你的設備並允許對倉庫進行 SSH 操作。</p><h3 id="綁定-的核心邏輯-ssh-密鑰對的作用" tabindex="-1">&quot;綁定&quot;的核心邏輯：SSH 密鑰對的作用 <a class="header-anchor" href="#綁定-的核心邏輯-ssh-密鑰對的作用" aria-label="Permalink to “&quot;綁定&quot;的核心邏輯：SSH 密鑰對的作用”">​</a></h3><p>SSH 認證依賴於密鑰對（公鑰 + 私鑰），它們是匹配的加密文件。生成後，你需要將&quot;公鑰&quot;提供給 GitHub（&quot;綁定&quot;），而&quot;私鑰&quot;留在本地設備上：</p><ol><li>私鑰：存儲在本地設備（如電腦）的指定目錄中（通常是 ~/.ssh/），充當&quot;你的專屬鑰匙&quot;，絕不能與任何人分享。</li><li>公鑰：這是一把可以公開分享的&quot;鎖&quot;——你需要將其複製到 GitHub 賬號的&quot;SSH keys list&quot;中（&quot;綁定&quot;操作）。</li></ol><p>當你通過 SSH 操作 GitHub 倉庫時（例如 git push <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:xxx/xxx.git）：</p><ul><li>你的本地設備使用私鑰加密&quot;操作請求&quot;併發送給 GitHub；</li><li>收到請求後，GitHub 嘗試使用你之前綁定的公鑰進行解密；</li><li>如果解密成功，你的設備被確認為已授權，操作被允許；否則，訪問被拒絕。</li></ul><h3 id="綁定-的具體步驟-核心流程" tabindex="-1">&quot;綁定&quot;的具體步驟（核心流程） <a class="header-anchor" href="#綁定-的具體步驟-核心流程" aria-label="Permalink to “&quot;綁定&quot;的具體步驟（核心流程）”">​</a></h3><p>一旦你理解了原理，實際操作就很簡單——核心是&quot;生成密鑰對 → 上傳公鑰到 GitHub&quot;：</p><ol><li><p>本地生成 SSH 密鑰對</p><ol><li>使用 Trae 獲取公鑰（推薦） 提示詞：<code>Help me create the SSH key needed for GitHub login. My email is your_email@gmail.com , Please return the public key for me to copy</code></li></ol><p><img src="'+G+'" alt=""></p><p>輸入提示詞後，你還需要在左側終端按 Enter 鍵，否則命令會一直等待而不執行。由於 Trae 無法幫你執行任何條件判斷，我們只需要一直按 Enter 即可。</p><p>最後，你會看到右側的 Trae 返回了它讀取的公鑰。你只需複製它並準備在下一步中粘貼。</p><p><img src="'+H+'" alt=""> 2. 手動獲取公鑰 打開你的本地終端（在 Windows 上使用 Git Bash 或 PowerShell；在 macOS/Linux 上使用終端），輸入以下命令（將 <a href="mailto:your_email@example.com" target="_blank" rel="noreferrer">your_email@example.com</a> 替換為你註冊 GitHub 賬號時使用的郵箱）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_email@example.com&quot;</span></span></code></pre></div><ol><li>按 Enter 接受默認值（默認文件路徑，無密碼，或根據需要設置密碼）。這將在 ~/.ssh/ 目錄中生成兩個文件： <ul><li>id_ed25519：私鑰（本地保存，<strong>絕不分享</strong>）；</li><li>id_ed25519.pub：公鑰（需要上傳到 GitHub）。</li></ul></li></ol></li><li><p>將公鑰&quot;綁定&quot;到你的 GitHub 賬號</p></li></ol><p>這是核心綁定步驟——將本地公鑰添加到 GitHub 賬號的&quot;SSH keys list&quot;中：</p><ol><li>複製公鑰內容： <ol><li>Trae：</li><li>Windows：用記事本打開 C:\\Users&lt;your&gt;.ssh\\id_ed25519.pub 並複製其所有內容；</li><li>macOS/Linux：在終端運行 cat ~/.ssh/id_ed25519.pub 並複製所有輸出（從開頭的 SSH-ed25519 到結尾的郵箱）。</li></ol></li><li>登錄 GitHub 並進入&quot;SSH Key Management&quot;頁面： <ol><li>點擊右上角頭像 → Settings → 左側菜單 SSH and GPG keys → 點擊 New SSH key。 <img src="'+S+'" alt=""><img src="'+q+'" alt=""></li><li>輸入任何標題（例如，your local computer&#39;s SSH），然後將你剛剛獲取的 SSH 公鑰粘貼到這裡。</li></ol></li></ol><p><img src="'+f+'" alt=""></p><p><img src="'+y+'" alt=""></p><ol start="3"><li>驗證綁定是否成功</li></ol><p>在終端中輸入以下命令（<strong>Trae 也可以做以下操作</strong>）來測試 GitHub 是否能識別你的設備：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span></code></pre></div><ul><li>如果你看到類似 Hi [your GitHub username]! You&#39;ve successfully authenticated... 的內容，說明你已成功綁定密鑰；</li><li>如果遇到錯誤，通常是因為公鑰複製不完整、私鑰權限過高（你的本地 ~/.ssh/ 目錄應僅由你讀寫）等。根據需要檢查這些問題。</li></ul><h3 id="重要注意事項" tabindex="-1">重要注意事項 <a class="header-anchor" href="#重要注意事項" aria-label="Permalink to “重要注意事項”">​</a></h3><p>如果你有多個設備（如筆記本電腦和臺式機），你需要為每個設備生成單獨的 SSH 密鑰對，並將每個公鑰綁定到同一個 GitHub 賬號——每個設備都有自己的&quot;門禁卡&quot;。</p><p>切勿分享你的私鑰（不要上傳到 GitHub 或與他人分享），否則有人可能會冒充你操作你的倉庫。如果私鑰洩露，請立即從 GitHub 刪除相應的公鑰並生成新的密鑰對。</p><p>綁定 SSH 後，使用 SSH 格式的倉庫地址（例如 <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:username/repository.git）進行操作，而不是 HTTPS 格式（例如 <a href="https://github.com/username/repository.git%EF%BC%89%E3%80%82%E5%A6%82%E6%9E%9C%E4%BD%A0%E4%B9%8B%E5%89%8D%E7%94%A8" target="_blank" rel="noreferrer">https://github.com/username/repository.git）。如果你之前用</a> HTTPS 克隆了倉庫，可以用 git remote set-url origin <code>&lt;new&gt;</code> 切換協議。</p><h1 id="使用-trae-進行-github-操作" tabindex="-1">使用 Trae 進行 GitHub 操作 <a class="header-anchor" href="#使用-trae-進行-github-操作" aria-label="Permalink to “使用 Trae 進行 GitHub 操作”">​</a></h1><p>我們已經解釋了什麼是 Git，什麼是 GitHub，什麼是 SSH，以及如何配置它。現在你可以自由使用 Trae 執行 Git 操作。首先，讓我們學習如何將遠程倉庫克隆到本地機器。</p><h2 id="git-clone-下載現有倉庫" tabindex="-1">Git clone : 下載現有倉庫 <a class="header-anchor" href="#git-clone-下載現有倉庫" aria-label="Permalink to “Git clone : 下載現有倉庫”">​</a></h2><p>你可以直接告訴它你想克隆的倉庫地址</p><p><img src="'+F+'" alt=""></p><h2 id="git-pull-從遠程倉庫獲取更新" tabindex="-1">Git pull : 從遠程倉庫獲取更新 <a class="header-anchor" href="#git-pull-從遠程倉庫獲取更新" aria-label="Permalink to “Git pull : 從遠程倉庫獲取更新”">​</a></h2><p>每次更新倉庫之前，由於它可能由多人維護，你需要先拉取最新的更改。之後，你可以修改並推送文件。</p><p><strong>記得包含文件夾名稱及其相對或絕對路徑，以避免推送到錯誤的倉庫。</strong></p><p>prompt:<code>Help me pull this repository AIID-TEST in ./AIID-TEST.</code></p><h2 id="git-commit-git-push-暫存更新並推送到-github" tabindex="-1">Git commit &amp; Git push : 暫存更新並推送到 GitHub <a class="header-anchor" href="#git-commit-git-push-暫存更新並推送到-github" aria-label="Permalink to “Git commit &amp; Git push : 暫存更新並推送到 GitHub”">​</a></h2><p>一切準備就緒後，你可以嘗試修改本地文件，在文件夾中添加或刪除項目。然後，讓 Trae 檢測更改並幫你推送到 GitHub。</p><p>prompt:<code>I finished. Commit and push to the repository AIID-TEST in ./AIID-TEST.</code></p><p><img src="'+_+'" alt=""></p><p>推送成功。現在你可以在 GitHub 上看到更新的內容了。</p><h1 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h1><ul><li>Pro Git book <a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">https://git-scm.com/book/en/v2</a></li><li>GitHub Docs <a href="https://docs.github.com/en" target="_blank" rel="noreferrer">https://docs.github.com/en</a></li></ul>',92)])])}const D=t(C,[["render",x]]);export{A as __pageData,D as default};
